from content_helpers import code, output, choice, lesson, section, program

def sections():
    return [section("data", "2. Данные и ввод", "Научите программу отвечать на входные данные.", [
        lesson("input", "int и std::cin", "Прочитайте числа и используйте их в вычислениях.",
            "Переменная — именованный объект, который хранит значение определённого типа. int count = 0; создаёт целочисленную переменную count с начальным значением 0. Имена чувствительны к регистру. std::cin >> count; читает целое число из стандартного ввода и помещает его в count. Несколько чисел можно прочитать цепочкой: std::cin >> price >> count;. Пробелы и переносы строк между числами служат разделителями.\n\nДля вывода переменной кавычки не нужны: std::cout << count;. Запись \"count\" вывела бы слово. Операторы + и * складывают и умножают числа. В учебных задачах этого раздела ввод гарантированно корректен и все результаты помещаются в int; обработку ошибочного ввода изучим позже. Не печатайте приглашения вроде «Введите число», если условие требует только ответ.",
            program('int price = 0;\nint count = 0;\nstd::cin >> price >> count;\nstd::cout << price * count;'),
            "int имеет конечный диапазон; стандарт C++ гарантирует не менее 16 бит, но не обещает ровно 32 бита на всех системах. В наших начальных задачах значения малы. Инициализация нулём не заменяет проверку ошибочного ввода, но исключает случайное чтение неинициализированного значения до ввода.",
            "Объявите переменные, прочитайте их через >>, вычислите результат и выведите через <<.", [
                code("cargo", "Груз в двух отсеках", 'Ввод: два целых числа a и b от 0 до 100. Выведите их сумму — общий груз.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nstd::cout << a + b;', [("12 8", "20"), ("0 0", "0"), ("100\n100", "200")], ["Для каждого отсека нужна переменная.", "После чтения выведите a + b."], "Цепочка ввода допускает пробел или перенос строки между числами."),
                output("literal", "Имя и значение", 'int count = 7;\nstd::cout << "count=" << count;', "count=7", ["Первое count находится в кавычках.", "Второе count обозначает значение переменной."], "Литерал выводит слово, а обращение к переменной — хранимое число."),
                code("fuel", "Топливо на рейсы", 'Ввод: расход топлива на один рейс f (0…100) и число рейсов n (0…100). Выведите суммарный расход.', 'int f = 0, n = 0;\nstd::cin >> f >> n;\nstd::cout << f * n;', [("9 4", "36"), ("10 0", "0"), ("100 100", "10000")], ["Один и тот же расход повторяется n раз.", "Используйте умножение f * n."], "Не нужно печатать единицы измерения: формат требует только число."),
                choice("read", "Куда направлена стрелка?", 'Какая инструкция читает число в уже объявленную переменную n?', ["std::cout << n;", "std::cin >> n;", 'std::cin >> "n";'], 1, ["Для ввода нужен cin.", "Ввод должен записать значение в объект, а не в строковый литерал."], "std::cin >> n читает в n; std::cout << n выводит значение n."),
                code("reverse", "Поменяйте порядок отчёта", 'Ввод: номера двух доков a и b (1…99). Выведите сначала b, затем a через один пробел.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nstd::cout << b << " " << a;', [("3 8", "8 3"), ("1 1", "1 1")], ["Читать нужно в исходном порядке.", 'В цепочке вывода начните с b и вставьте " ".'], "Переменные позволяют использовать данные в другом порядке, чем они пришли.")
            ], ["int", "cin", "арифметика"]),
        lesson("assignment", "Присваивание и состояние", "Проследите, как программа меняет значения.",
            "int energy = 20; — создание с начальным значением. energy = 12; — изменение уже созданного объекта. Сначала вычисляется правая часть присваивания, затем результат сохраняется слева: energy = energy + 5; увеличивает прежнее значение на 5. Это не математическое равенство.\n\nСокращённая запись energy += 5; делает то же для нашей целочисленной переменной. Аналогично -= и *=. После присваивания старое значение теряется, если вы не сохранили его отдельно. Для обмена значениями заведите временную переменную: int saved = a; a = b; b = saved;. Имена должны начинаться с буквы или подчёркивания; для учебного кода выбирайте понятные латинские имена без зарезервированных шаблонов.",
            program('int energy = 20;\nenergy -= 3;\nenergy += 8;\nstd::cout << energy;'),
            "Правая часть использует состояние до записи результата. В a = b; копируется значение b, а не создаётся постоянная связь между переменными. Изменение b после этого не меняет a. Связанные имена — ссылки — появятся в отдельном разделе.",
            "Выписывайте значение после каждой инструкции. Не пытайтесь читать присваивание как уравнение.", [
                code("battery", "Заряд дрона", 'Ввод: начальный заряд e (0…100), зарядка add (0…100), расход used (0…100), причём used ≤ e + add. Измените e и выведите остаток.', 'int e = 0, add = 0, used = 0;\nstd::cin >> e >> add >> used;\ne += add;\ne -= used;\nstd::cout << e;', [("30 20 12", "38"), ("0 10 10", "0")], ["Сначала прибавьте зарядку, затем вычтите расход.", "Используйте e += add и e -= used."], "Все изменения идут последовательно; состояние e хранит текущий заряд."),
                output("copy", "Копия не связь", 'int a = 4;\nint b = a;\na = 9;\nstd::cout << a << " " << b;', "9 4", ["b получил значение в момент инициализации.", "После изменения a переменная b не меняется."], "Простое копирование int создаёт независимое значение."),
                code("swap", "Перестановка контейнеров", 'Ввод: два целых числа a и b от −100 до 100. Обменяйте значения переменных через третью переменную и выведите новые a и b через пробел.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nint saved = a;\na = b;\nb = saved;\nstd::cout << a << " " << b;', [("5 -2", "-2 5"), ("0 0", "0 0")], ["Первое присваивание иначе уничтожит одно из значений.", "Сначала сохраните a, затем перепишите a и восстановите b из saved."], "Вывод b a без обмена дал бы тот же текст, но не выполнил бы требование изменить переменные.", difficulty=2),
                choice("equal", "Не уравнение", 'Что делает x = x + 1; для int x = 5;?', ["Утверждает невозможное равенство", "Сохраняет 6 в x", "Сравнивает x с 6"], 1, ["Сначала вычисляется правая часть.", "Знак = записывает результат в левую переменную."], "Сравнение равенства в C++ записывается ==, а не =."),
                code("inventory", "Склад после двух рейсов", 'Ввод: boxes (0…100), taken (0…boxes), arrived (0…100). Сначала со склада забрали taken ящиков, затем привезли arrived. Выведите старое и новое количество через пробел.', 'int boxes = 0, taken = 0, arrived = 0;\nstd::cin >> boxes >> taken >> arrived;\nint before = boxes;\nboxes -= taken;\nboxes += arrived;\nstd::cout << before << " " << boxes;', [("20 7 4", "20 17"), ("0 0 3", "0 3")], ["Для отчёта нужно сохранить исходное количество.", "Скопируйте boxes в before до изменения."], "История состояния не сохраняется автоматически; нужное прошлое значение храните явно.", difficulty=2)
            ], ["присваивание", "состояние", "обмен"]),
        lesson("types", "double, char и bool", "Выбирайте тип под смысл данных.",
            "double хранит числа с дробной частью: double distance = 2.5;. В C++ дробную часть в исходном коде отделяют точкой. int хранит целые; дробная часть при преобразовании double в int отбрасывается в сторону нуля, если результат представим.\n\nchar marker = 'A'; хранит один кодовый элемент символа в одинарных кавычках; \"A\" — строковый литерал, а не char. В UTF-8 русский символ обычно занимает несколько байтов, поэтому не обещаем хранить любую букву в одном char. bool ready = true; хранит true или false. Без специальных настроек вывод bool даёт 1 или 0.\n\nДля фиксированного числа знаков после точки подключите <iomanip> и выведите std::fixed << std::setprecision(2). Это настройка форматирования потока, не изменение хранимого числа. В задачах корректный числовой ввод использует точку.",
            program('double price = 2.5;\nchar label = \'A\';\nbool ready = true;\nstd::cout << label << " " << ready << " " << std::fixed << std::setprecision(2) << price;', "iostream iomanip"),
            "Большинство десятичных дробей нельзя представить точно в двоичной системе floating point. Форматирование 2 знаками не делает вычисления точной денежной арифметикой. Для реальных денежных сумм обычно используют целые минимальные единицы или специально выбранную модель. Здесь double — учебная модель измерений.",
            "Числа без кавычек, один char в одинарных, текст в двойных. Форматирование отделяйте от вычисления.", [
                code("distance", "Лазерный дальномер", 'Ввод: два неотрицательных расстояния double от 0 до 1000 с точкой. Выведите их сумму с ровно двумя знаками после точки.', 'double a = 0, b = 0;\nstd::cin >> a >> b;\nstd::cout << std::fixed << std::setprecision(2) << a + b;', [("1.25 2.5", "3.75"), ("0 2", "2.00")], ["Для дробей нужен double.", "Перед суммой настройте fixed и setprecision(2)."], "Точность 2 при fixed означает два знака после точки.", headers="iostream iomanip"),
                output("bool", "Индикаторы состояния", 'char gate = \'B\';\nbool open = false;\nstd::cout << gate << ":" << open;', "B:0", ["char печатается как символ.", "false без boolalpha печатается как 0."], "Это стандартное форматирование bool в ненастроенном потоке."),
                code("badge", "Код сектора", 'Ввод: одна латинская заглавная буква. Прочитайте её в char и выведите Sector: и букву через один пробел.', 'char sector = \'A\';\nstd::cin >> sector;\nstd::cout << "Sector: " << sector;', [("K", "Sector: K"), ("A", "Sector: A")], ["Для одного латинского символа достаточно char.", "Считывайте в переменную, а не в литерал."], "Ограничение латиницей позволяет не путать char с многобайтовым русским символом."),
                choice("precision", "Точность — не магия", 'Что гарантирует fixed << setprecision(2) при выводе double?', ["Любая десятичная дробь хранится точно", "В выводе два знака после точки", "Все последующие вычисления становятся целочисленными"], 1, ["Это настройка потока вывода.", "Тип и значение переменной она не меняет."], "Округлённый внешний вид не отменяет ограниченной точности floating point."),
                code("temperature", "Средняя температура", 'Ввод: два измерения double от −100 до 100. Выведите их среднее арифметическое с одним знаком после точки.', 'double a = 0, b = 0;\nstd::cin >> a >> b;\nstd::cout << std::fixed << std::setprecision(1) << (a + b) / 2.0;', [("10 15", "12.5"), ("-4 2", "-1.0")], ["Сначала сложите два измерения.", "Скобки вокруг a + b нужны до деления на 2.0."], "Скобки отражают формулу среднего. Здесь операнды double, поэтому деление вещественное.", headers="iostream iomanip", difficulty=2)
            ], ["типы", "форматирование", "double"]),
        lesson("tickets", "Мини-проект: билетная касса", "Объедините ввод, состояние и точный отчёт.",
            "В кассе удобнее хранить цену в целых монетах, если условие не требует дробных денежных величин. Сначала прочитайте входные значения, затем вычислите стоимость и остаток, затем сформируйте отчёт. Не смешивайте приглашения ко вводу с требуемым ответом.\n\nВ этом мини-проекте условия гарантируют достаточный бюджет, поэтому ветвления не нужны. Если вы хотите проверить произвольный ввод пользователя, потребуется обработка ошибок и выбор — это следующие темы. Разделяйте гарантии задачи и гарантии языка.",
            program('int price = 0, count = 0, paid = 0;\nstd::cin >> price >> count >> paid;\nint total = price * count;\nstd::cout << "Total: " << total << "\\nChange: " << paid - total;'),
            "Ограничение входа — часть контракта задачи. Например, paid ≥ price * count позволяет вычислить неотрицательную сдачу без if. Это не делает программу защищённой от любого ввода. В реальном приложении ввод проверяют отдельно.",
            "Определите единицы измерения, ограничения и формат. Сохраняйте промежуточные результаты с понятными именами.", [
                code("total", "Печать чека", 'Ввод: цена p (0…100), количество n (0…100), оплата paid (p*n…20000). Выведите две строки: Total: <стоимость> и Change: <сдача>.', 'int p = 0, n = 0, paid = 0;\nstd::cin >> p >> n >> paid;\nint total = p * n;\nstd::cout << "Total: " << total << "\\nChange: " << paid - total;', [("7 3 25", "Total: 21\nChange: 4"), ("0 5 0", "Total: 0\nChange: 0")], ["Стоимость — произведение, сдача — разность.", "Сохраните стоимость в total и используйте её дважды."], "Промежуточная переменная снижает риск разойтись в двух частях отчёта.", difficulty=2),
                output("trace", "История кассы", 'int balance = 30;\nint receipt = balance;\nbalance -= 12;\nstd::cout << receipt << " " << balance;', "30 18", ["receipt создаётся до изменения balance.", "Вычитание не меняет уже созданную копию."], "Сохранённая копия отражает прошлое состояние."),
                code("packages", "Две группы пассажиров", 'Ввод: adult (0…20), child (0…20). Взрослый билет стоит 12 монет, детский — 7. Выведите общую стоимость.', 'int adult = 0, child = 0;\nstd::cin >> adult >> child;\nstd::cout << adult * 12 + child * 7;', [("2 3", "45"), ("0 4", "28")], ["Посчитайте стоимость каждой группы отдельно.", "Сложите adult * 12 и child * 7."], "Умножение выполняется раньше сложения; выражение соответствует двум группам.", difficulty=2),
                choice("contract", "Что обещано условием?", 'Условие гарантирует корректный ввод и достаточную оплату. Что следует из этого?', ["Любой пользовательский ввод безопасен", "Для решения этой задачи можно не добавлять ветвление для нехватки денег", "Тип int может хранить любое число"], 1, ["Гарантии относятся только к входам этой задачи.", "Не распространяйте контракт на все возможные данные."], "В тестах задачи соблюдаются ограничения. Защита реального продукта требует дополнительных проверок."),
                code("budget", "Остаток бюджета экспедиции", 'Ввод: budget (0…20000), price (0…100), crew (0…100), причём budget ≥ price*crew. Выведите crew, стоимость и остаток на трёх отдельных строках без подписей.', 'int budget = 0, price = 0, crew = 0;\nstd::cin >> budget >> price >> crew;\nint total = price * crew;\nstd::cout << crew << "\\n" << total << "\\n" << budget - total;', [("100 8 9", "9\n72\n28"), ("0 0 0", "0\n0\n0")], ["Порядок вывода отличается от порядка ввода.", "Промежуточная total пригодится в двух строках."], "Выбор порядка вывода и сохранение вычисленной стоимости связывают навыки всего раздела.", difficulty=2)
            ], ["мини-проект", "ввод", "состояние"])
    ])]
